const input = $input.first().json;
const body = input.body ?? input;
const msg = body.message ?? {};
const call = msg.call ?? {};
const tc = (msg.toolCallList && msg.toolCallList[0]) || (msg.toolCalls && msg.toolCalls[0]) || {};
let args = tc.arguments ?? tc.function?.arguments ?? {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
const toStr = v => (typeof v === 'string' && v.trim() !== '') ? v.trim() : undefined;
const phone = String(call.customer?.number || args.phone || `web-${String(call.id || 'test').slice(0, 8)}`).replace(/\s+/g, '');

const ENUMS = {
  property_type: ['single_family','condo','townhouse','multi_family','land','other'],
  timeline: ['asap','within_1_month','1_3_months','3_6_months','6_plus_months','just_browsing'],
  financing_status: ['cash','pre_approved','in_process','not_started','unknown'],
};
const toNum = v => {
  if (v === undefined || v === null || v === '') return undefined;
  const n = Number(String(v).replace(/[$,\s]/g, ''));
  return Number.isFinite(n) ? n : undefined;
};
const toBool = v => {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string') {
    const s = v.trim().toLowerCase();
    if (['true', 'yes', 'y'].includes(s)) return true;
    if (['false', 'no', 'n'].includes(s)) return false;
  }
  return undefined;
};
const ALIASES = { preapproved: 'pre_approved', pre_approval: 'pre_approved', prequalified: 'pre_approved', single_family_home: 'single_family',
  house: 'single_family', condominium: 'condo', townhome: 'townhouse', multifamily: 'multi_family', immediately: 'asap',
  '1_month': 'within_1_month', '3_months': '1_3_months', '6_months': '3_6_months', browsing: 'just_browsing' };
const toEnum = (k, v) => {
  let s = toStr(v)?.toLowerCase().replace(/[\s-]+/g, '_');
  if (s && ALIASES[s]) s = ALIASES[s];
  return s && ENUMS[k].includes(s) ? s : undefined;
};

const beds = toNum(args.bedrooms);
const candidate = {
  phone,
  full_name: toStr(args.full_name),
  email: toStr(args.email)?.toLowerCase(),
  location_pref: toStr(args.location_pref),
  property_type: toEnum('property_type', args.property_type),
  bedrooms: beds === undefined ? undefined : Math.round(beds),
  budget_min: toNum(args.budget_min),
  budget_max: toNum(args.budget_max),
  timeline: toEnum('timeline', args.timeline),
  financing_status: toEnum('financing_status', args.financing_status),
  has_other_agent: toBool(args.has_other_agent),
  first_time_buyer: toBool(args.first_time_buyer),
  must_haves: toStr(args.must_haves),
  notes: toStr(args.notes),
};
// Only send fields the caller actually provided, so an upsert never wipes existing data.
const payload = {};
for (const [k, v] of Object.entries(candidate)) if (v !== undefined) payload[k] = v;
payload.last_call_at = new Date().toISOString();

return [{ json: { toolCallId: tc.id, phone, payload } }];

const row = $input.first().json;
const ctx = $('Parse Upsert').first().json;
if (!row || !row.id) {
  return [{ json: { toolCallId: ctx.toolCallId, result: 'Save failed. Do not mention this to the caller. Continue the conversation normally and keep asking questions.' } }];
}
const KEY = ['location_pref', 'property_type', 'budget_max', 'timeline', 'financing_status', 'has_other_agent'];
const OPTIONAL = ['full_name', 'bedrooms'];
const isMissing = f => row[f] === null || row[f] === undefined || row[f] === '';
const missingKey = KEY.filter(isMissing);
const missingOpt = OPTIONAL.filter(isMissing);

let next;
if (missingKey.length) next = `continue_questions (still need: ${[...missingKey, ...missingOpt].join(', ')})`;
else if (row.tier === 'hot') next = 'offer_booking';
else next = 'wrap_up_no_booking';

return [{ json: { toolCallId: ctx.toolCallId, result: `Saved. tier=${row.tier}. NEXT=${next}` } }];

const input = $input.first().json;
const body = input.body ?? input;
const msg = body.message ?? {};
const call = msg.call ?? {};
const tc = (msg.toolCallList && msg.toolCallList[0]) || (msg.toolCalls && msg.toolCalls[0]) || {};
let args = tc.arguments ?? tc.function?.arguments ?? {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
const toStr = v => (typeof v === 'string' && v.trim() !== '') ? v.trim() : undefined;
const phone = String(call.customer?.number || args.phone || `web-${String(call.id || 'test').slice(0, 8)}`).replace(/\s+/g, '');

const TZ = 'America/New_York';
const MIN_NOTICE_HOURS = 3;

let from = DateTime.now().setZone(TZ).plus({ hours: MIN_NOTICE_HOURS });
from = from.plus({ minutes: (30 - (from.minute % 30)) % 30 }).set({ second: 0, millisecond: 0 });

const pref = toStr(args.preferred_day);
if (pref && /^\d{4}-\d{2}-\d{2}$/.test(pref)) {
  const p = DateTime.fromISO(pref, { zone: TZ }).startOf('day');
  if (p.isValid && p > from) from = p;
}
const to = from.startOf('day').plus({ days: 8 });

return [{ json: { toolCallId: tc.id, timeMin: from.toISO(), timeMax: to.toISO() } }];

const TZ = 'America/New_York';
const START_H = 9, END_H = 17, SLOT_MIN = 30, MAX_OFFERS = 3;   // Mon-Fri 9am-5pm ET, 30-min calls

const ctx = $('Parse Availability').first().json;
const res = $input.first().json;
const cal = Object.values(res.calendars || {})[0];
if (!cal || cal.errors || res.error) {
  return [{ json: { toolCallId: ctx.toolCallId, result: 'Calendar unavailable. Do not offer any times. Tell the caller a team member will call them shortly to schedule, and note that with upsert_lead.' } }];
}
const busy = (cal.busy || []).map(b => ({ s: DateTime.fromISO(b.start), e: DateTime.fromISO(b.end) }));

const from = DateTime.fromISO(ctx.timeMin, { zone: TZ });
const to = DateTime.fromISO(ctx.timeMax, { zone: TZ });
const slots = [];
for (let d = from.startOf('day'); d < to; d = d.plus({ days: 1 })) {
  if (d.weekday > 5) continue;
  const dayEnd = d.set({ hour: END_H, minute: 0 });
  for (let t = d.set({ hour: START_H, minute: 0 }); t.plus({ minutes: SLOT_MIN }) <= dayEnd; t = t.plus({ minutes: SLOT_MIN })) {
    const e = t.plus({ minutes: SLOT_MIN });
    if (t >= from && !busy.some(b => t < b.e && e > b.s)) slots.push(t);
  }
}

// Spread offers: first slot of each of the next days, then later slots if fewer than 3 days are open.
const byDay = {};
for (const s of slots) (byDay[s.toISODate()] ??= []).push(s);
const days = Object.keys(byDay).sort();
const picked = [];
for (let round = 0; round < 6 && picked.length < MAX_OFFERS; round++) {
  for (const k of days) {
    const s = byDay[k][round * 3];
    if (s && picked.length < MAX_OFFERS) picked.push(s);
  }
}
picked.sort((a, b) => a.toMillis() - b.toMillis());

if (!picked.length) {
  return [{ json: { toolCallId: ctx.toolCallId, result: 'No openings in the next week. Tell the caller a team member will call them shortly to schedule, and note that with upsert_lead.' } }];
}
const list = picked.map((s, i) => `${i + 1}) ${s.toFormat("cccc, LLLL d 'at' h:mm a")} [start_time=${s.toISO()}]`).join('; ');
return [{ json: { toolCallId: ctx.toolCallId, result: `Available times (Eastern): ${list}. Read only the day and time to the caller. Pass the exact start_time value to book_appointment.` } }];

const input = $input.first().json;
const body = input.body ?? input;
const msg = body.message ?? {};
const call = msg.call ?? {};
const tc = (msg.toolCallList && msg.toolCallList[0]) || (msg.toolCalls && msg.toolCalls[0]) || {};
let args = tc.arguments ?? tc.function?.arguments ?? {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
const toStr = v => (typeof v === 'string' && v.trim() !== '') ? v.trim() : undefined;
const phone = String(call.customer?.number || args.phone || `web-${String(call.id || 'test').slice(0, 8)}`).replace(/\s+/g, '');

let start = DateTime.fromISO(String(args.start_time || ''), { setZone: true });
const invalid = !start.isValid;
if (invalid) start = DateTime.now();
const end = start.plus({ minutes: 30 });
return [{ json: {
  toolCallId: tc.id, phone, invalid,
  start: start.toISO(), end: end.toISO(),
  full_name: toStr(args.full_name), email: toStr(args.email)?.toLowerCase(),
} }];

const ctx = $('Parse Booking').first().json;
const leadItem = $('Get Lead').first()?.json || {};
const res = $input.first().json;
const cal = Object.values(res.calendars || {})[0];

let problem = null;
if (ctx.invalid) problem = 'invalid';
else if (!cal || cal.errors || res.error) problem = 'calendar_error';
else if ((cal.busy || []).length) problem = 'taken';

let result = null;
if (problem === 'taken' || problem === 'invalid') result = 'That time is no longer available. Apologize briefly and call check_availability again to offer new times.';
else if (problem === 'calendar_error') result = 'Booking system unavailable. Do not retry. Tell the caller a team member will call them shortly to schedule, and note that with upsert_lead.';

return [{ json: { ...ctx, lead: leadItem.id ? leadItem : null, problem, result } }];

const TZ = 'America/New_York';
const LABEL = {
  timeline: { asap: 'ASAP', within_1_month: 'within a month', '1_3_months': '1-3 months', '3_6_months': '3-6 months', '6_plus_months': '6+ months', just_browsing: 'just browsing' },
  financing_status: { cash: 'cash buyer', pre_approved: 'pre-approved', in_process: 'working with a lender', not_started: 'not started', unknown: 'unknown' },
  property_type: { single_family: 'single-family home', condo: 'condo', townhouse: 'townhouse', multi_family: 'multi-family', land: 'land', other: 'property' },
};
const lab = (k, v) => (v ? (LABEL[k][v] || String(v).replace(/_/g, ' ')) : 'not given');

const c = $input.first().json;
const l = c.lead || {};
const name = c.full_name || l.full_name || 'Buyer';
const email = c.email || l.email;
const money = n => (n ? '$' + Number(n).toLocaleString('en-US') : 'n/a');
const desc = [
  'Buyer lead from the AI phone agent',
  `Phone: ${c.phone}`,
  email ? `Email: ${email}` : null,
  `Looking for: ${l.bedrooms ? l.bedrooms + '-bed ' : ''}${lab('property_type', l.property_type)} in ${l.location_pref || 'n/a'}`,
  `Budget: up to ${money(l.budget_max)}`,
  `Timeline: ${lab('timeline', l.timeline)}`,
  `Financing: ${lab('financing_status', l.financing_status)}`,
  l.must_haves ? `Must-haves: ${l.must_haves}` : null,
  l.notes ? `Notes: ${l.notes}` : null,
].filter(Boolean).join('\n');

const wants = [l.bedrooms ? `${l.bedrooms}-bed` : null, l.property_type ? lab('property_type', l.property_type) : null, l.location_pref ? `in ${l.location_pref}` : null].filter(Boolean).join(' ');

const eventBody = {
  summary: `Buyer call - ${name}${wants ? ' - ' + wants : ''}`,
  description: desc,
  start: { dateTime: c.start, timeZone: TZ },
  end: { dateTime: c.end, timeZone: TZ },
  reminders: { useDefault: true },
};
if (email) eventBody.attendees = [{ email }];
return [{ json: { ...c, name, email, eventBody } }];

const TZ = 'America/New_York';
const LABEL = {
  timeline: { asap: 'ASAP', within_1_month: 'within a month', '1_3_months': '1-3 months', '3_6_months': '3-6 months', '6_plus_months': '6+ months', just_browsing: 'just browsing' },
  financing_status: { cash: 'cash buyer', pre_approved: 'pre-approved', in_process: 'working with a lender', not_started: 'not started', unknown: 'unknown' },
  property_type: { single_family: 'single-family home', condo: 'condo', townhouse: 'townhouse', multi_family: 'multi-family', land: 'land', other: 'property' },
};
const lab = (k, v) => (v ? (LABEL[k][v] || String(v).replace(/_/g, ' ')) : 'not given');

const ev = $input.first().json;
const c = $('Build Event').first().json;
const l = c.lead || {};

const when = DateTime.fromISO(c.start, { setZone: true }).setZone(TZ).toFormat("ccc, LLL d 'at' h:mm a") + ' ET';
const money = n => (n ? '$' + Number(n).toLocaleString('en-US') : null);
const budget = l.budget_min && l.budget_max ? `${money(l.budget_min)} - ${money(l.budget_max)}` : (money(l.budget_max) ? `up to ${money(l.budget_max)}` : 'not given');
const agent = l.has_other_agent === true ? 'Yes' : l.has_other_agent === false ? 'No' : 'unknown';
const wants = `${l.bedrooms ? l.bedrooms + '-bed ' : ''}${lab('property_type', l.property_type)} in ${l.location_pref || 'area not given'}`;

const owner = ev.organizer?.email || ev.creator?.email;
const link = ev.htmlLink && owner ? `${ev.htmlLink}${ev.htmlLink.includes('?') ? '&' : '?'}authuser=${encodeURIComponent(owner)}` : ev.htmlLink;

const slackText = [
  ':fire: *Hot lead - appointment booked*',
  `*${c.name}*  |  ${c.phone}${c.email ? '  |  ' + c.email : ''}`,
  `*Looking to buy:* ${wants}`,
  `*Budget:* ${budget}   *Timeline:* ${lab('timeline', l.timeline)}   *Financing:* ${lab('financing_status', l.financing_status)}   *Other agent:* ${agent}`,
  l.must_haves ? `*Must-haves:* ${l.must_haves}` : null,
  l.notes ? `*Notes:* ${l.notes}` : null,
  `*Appointment:* ${when}${link ? `  (<${link}|open in Google Calendar>)` : ''}`,
  `*Lead score:* ${l.lead_score ?? 'n/a'}/100`,
].filter(Boolean).join('\n');

const leadPatch = { status: 'appointment_booked' };
if (c.full_name) leadPatch.full_name = c.full_name;
if (c.email) leadPatch.email = c.email;

const appointment = {
  lead_id: l.id ?? null, phone: c.phone, start_time: c.start, end_time: c.end,
  google_event_id: ev.id, calendar_link: ev.htmlLink ?? null,
};
return [{ json: { toolCallId: c.toolCallId, phone: c.phone, when, leadPatch, appointment, slackText } }];

const input = $input.first().json;
const body = input.body ?? input;
const m = body.message ?? {};
const call = m.call ?? {};
const row = {
  vapi_call_id: call.id ?? m.callId ?? null,
  phone: call.customer?.number ?? null,
  started_at: m.startedAt ?? call.startedAt ?? null,
  ended_at: m.endedAt ?? call.endedAt ?? null,
  duration_seconds: m.durationSeconds != null ? Math.round(m.durationSeconds) : null,
  ended_reason: m.endedReason ?? call.endedReason ?? null,
  summary: m.analysis?.summary ?? m.summary ?? null,
  transcript: m.artifact?.transcript ?? m.transcript ?? null,
  recording_url: m.artifact?.recordingUrl ?? m.recordingUrl ?? null,
  cost: m.cost ?? null,
};
return [{ json: { row } }];
